package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.speech.tts.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.*;
public class OfflineVoicesFifteenTest extends Instrumentation {
    void check(boolean yes,String message){if(!yes)throw new AssertionError(message);}
    void ui(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier condition,String message)throws Exception{long until=SystemClock.elapsedRealtime()+35000;while(SystemClock.elapsedRealtime()<until){AtomicBoolean ready=new AtomicBoolean();ui(()->ready.set(condition.getAsBoolean()));if(ready.get())return;Thread.sleep(50);}throw new AssertionError(message);}
    void shell(String command)throws Exception{try(InputStream input=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(command))){byte[] bytes=new byte[256];while(input.read(bytes)!=-1){}}}
    void screenshot(String name)throws Exception{waitForIdleSync();Thread.sleep(350);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}
    public void onCreate(Bundle state){super.onCreate(state);start();}
    public void onStart(){Bundle result=new Bundle();Context context=getTargetContext();SharedPreferences prefs=context.getSharedPreferences("reading_settings",0);Map<String,?> backup=new HashMap<>(prefs.getAll());OfflineVoicesActivity activity=null;boolean passed=false;try{
        check(!context.getSystemService(KeyguardManager.class).isKeyguardLocked(),"Unlock phone for voice catalogue verification");activity=(OfflineVoicesActivity)startActivitySync(new Intent(context,OfflineVoicesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final OfflineVoicesActivity a=activity;await(()->a.system!=null&&a.system.initialized,"voice enumeration not ready");ui(()->{check(a.headers.size()==15&&a.states.size()==15,"not all 15 languages visible");for(String language:VoiceLanguages.CODES){check(a.headers.containsKey(language),"missing language row: "+language);for(OfflineVoicesActivity.Item item:a.items(language))if(item.option!=null)check(SystemSpeaker.offlineUsable(item.option.voice)&&VoiceLanguages.matches(language,item.option.voice.getLocale()),"wrong/uninstalled voice in "+language);}check(!a.items("fr").isEmpty(),"user's downloaded French voice still missing");a.expanded="fr";a.render();check(!a.voiceRows.isEmpty(),"French voices not displayed");check(a.engineButtons.containsKey("com.google.android.tts:fr:delete")&&a.engineButtons.containsKey("com.google.android.tts:fr:redownload"),"French remove/redownload actions missing");});waitForIdleSync();ui(()->{View group=(View)a.headers.get("fr").getParent().getParent().getParent();a.scroll.scrollTo(0,group.getTop()-a.dp(8));});screenshot("offline-voices-french.png");
        OfflineVoicesActivity.Item french=a.items("fr").get(0);String chinese=prefs.getString("chineseVoiceKey",""),active=prefs.getString("systemVoiceKey","");ui(()->{a.voiceRows.get(french.key).container.performClick();check(prefs.getString("voice_fr","").equals(french.option.key),"French preference not saved separately");check(prefs.getString("chineseVoiceKey","").equals(chinese),"French overwrote Chinese preference");check(prefs.getString("systemVoiceKey","").equals(active),"French selection replaced active zh/en/ja voice");check(a.previewKey.isEmpty(),"selection auto-played");a.voiceRows.get(french.key).play.performClick();});await(()->a.previewStarted,"actual French preview did not start");ui(()->{a.voiceRows.get(french.key).play.performClick();check(a.previewKey.isEmpty()&&!a.guard.held,"French preview pause failed");});
        ui(()->{ArrayList<SystemSpeaker.Option> original=new ArrayList<>(a.system.options);a.system.options.removeIf(option->VoiceLanguages.matches("de",option.voice.getLocale()));Voice uninstalled=new Voice("qa-uninstalled-de",Locale.GERMANY,Voice.QUALITY_NORMAL,Voice.LATENCY_NORMAL,false,new HashSet<>(Collections.singletonList(TextToSpeech.Engine.KEY_FEATURE_NOT_INSTALLED)));a.system.options.add(new SystemSpeaker.Option(french.option.engine,"Google",uninstalled,french.option.tts,999));a.expanded="de";a.render();check(a.items("de").isEmpty()&&a.states.get("de").getText().toString().equals(a.getString(R.string.speech_not_downloaded)),"uninstalled offline package not shown as missing download");check(a.engineButtons.get("com.google.android.tts:de").getText().toString().equals(a.getString(R.string.speech_install)),"missing download button");a.system.options.removeIf(option->VoiceLanguages.matches("de",option.voice.getLocale()));a.render();check(a.states.get("de").getText().toString().equals(a.getString(R.string.speech_not_offered)),"unsupported and not downloaded conflated");a.system.options.clear();a.system.options.addAll(original);a.expanded="fr";a.render();});
        int installed=a.items("fr").size();for(String operation:new String[]{"delete","redownload"}){SystemSpeaker before=a.system;ui(()->a.engineButtons.get("com.google.android.tts:fr:"+operation).performClick());await(()->!a.visible,"engine page not opened for "+operation);check(a.previewKey.isEmpty()&&!a.guard.held,"engine transition kept preview");shell("input keyevent 4");await(()->a.visible&&a.system!=null&&a.system.initialized&&a.system!=before,"return did not refresh "+operation);ui(()->check(a.items("fr").size()==installed,"test altered user's French package"));}
        result.putInt("installedFrenchVoices",installed);result.putString("result","PASS: 15 language rows; downloaded French shown; real French preview/pause; unique French preference; no automatic preview; missing-download vs not-offered states; delete/redownload route to real engine page; return refresh; user's installed package preserved");passed=true;
    }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));}finally{if(activity!=null){final OfflineVoicesActivity a=activity;ui(a::finish);}SharedPreferences.Editor restore=prefs.edit().clear();for(Map.Entry<String,?> entry:backup.entrySet()){String key=entry.getKey();Object value=entry.getValue();if(value instanceof String)restore.putString(key,(String)value);else if(value instanceof Integer)restore.putInt(key,(Integer)value);else if(value instanceof Long)restore.putLong(key,(Long)value);else if(value instanceof Boolean)restore.putBoolean(key,(Boolean)value);else if(value instanceof Float)restore.putFloat(key,(Float)value);}restore.commit();}finish(passed?-1:0,result);}
}
